import java.util.List;

public class LruEvictionCacheTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String keys(LruEvictionCache cache) {
        try {
            List<String> k = cache.keysLeastRecentFirst();
            return k == null ? "null" : k.toString();
        } catch (RuntimeException e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        LruEvictionCache cache = new LruEvictionCache(2);
        cache.put("a", 1);
        cache.put("b", 2);
        check("keys after two puts", "[a, b]", keys(cache));
        check("get(a)", Integer.valueOf(1), cache.get("a"));
        check("a is now most recent", "[b, a]", keys(cache));
        cache.put("c", 3);
        check("least recently used evicted", "[a, c]", keys(cache));
        check("evicted key is gone", null, cache.get("b"));
        check("evictionCount", 1, cache.evictionCount());
        check("size stays at capacity", 2, cache.size());

        LruEvictionCache overwrite = new LruEvictionCache(2);
        overwrite.put("x", 1);
        overwrite.put("y", 2);
        overwrite.put("x", 10);
        check("overwrite refreshes order", "[y, x]", keys(overwrite));
        check("overwrite stores the new value", Integer.valueOf(10), overwrite.get("x"));
        check("overwrite evicts nothing", 0, overwrite.evictionCount());

        LruEvictionCache misses = new LruEvictionCache(1);
        misses.put("only", 5);
        check("miss returns null", null, misses.get("nope"));
        check("miss changes nothing", "[only]", keys(misses));
        misses.put("next", 6);
        check("capacity 1 evicts", "[next]", keys(misses));
        check("two evictions never happened", 1, misses.evictionCount());

        String bad = "no exception";
        try {
            new LruEvictionCache(0);
        } catch (IllegalArgumentException e) {
            bad = "IAE";
        } catch (RuntimeException e) {
            bad = "wrong: " + e.getClass().getSimpleName();
        }
        check("capacity 0 rejected", "IAE", bad);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

