import java.util.ArrayList;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class LruEvictionCache {

    private final int capacity;
    private final Map<String, Integer> entries = new LinkedHashMap<>();
    private int evictions = 0;

    public LruEvictionCache(int capacity) {
        if (capacity < 1) {
            throw new IllegalArgumentException("capacity must be at least 1");
        }
        this.capacity = capacity;
    }

    public Integer get(String key) {
        if (!entries.containsKey(key)) {
            return null;
        }
        Integer value = entries.remove(key);
        entries.put(key, value);
        return value;
    }

    public void put(String key, int value) {
        boolean known = entries.containsKey(key);
        if (known) {
            entries.remove(key);
        } else if (entries.size() >= capacity) {
            Iterator<String> oldest = entries.keySet().iterator();
            oldest.next();
            oldest.remove();
            evictions++;
        }
        entries.put(key, value);
    }

    public List<String> keysLeastRecentFirst() {
        return new ArrayList<>(entries.keySet());
    }

    public int size() {
        return entries.size();
    }

    public int evictionCount() {
        return evictions;
    }
}
